  const s = r / 0.62;
  shrubItems.push({ x: cx, y: cy - 0.04, z: cz, sx: 1.25 * s, sy: 1.05 * s * (sy / 0.72), sz: 1.1 * s, ry: R(0, Math.PI * 2), v: Math.floor(rand() * 3), k: R(0.93, 1.07) + tint * 0.12 });
